class WalletOptionsButton extends ConsumerWidget {
  const WalletOptionsButton({
    super.key,
    required this.walletId,
    this.showKeys = true,
  });

  final String walletId;

  /// A watch-only wallet of a single address has no keys to show.
  final bool showKeys;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final wallet = ref.read(pWallets).getWallet(walletId);
    return RawMaterialButton(
      constraints: const BoxConstraints(minHeight: 32, minWidth: 32),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(1000)),
      onPressed: () async {
        final func = await showDialog<_WalletOptions?>(
          context: context,
          barrierColor: Colors.transparent,
          builder: (context) {
            return WalletOptionsPopupMenu(
              onSignMessagePressed: () =>
                  Navigator.of(context).pop(_WalletOptions.signMessage),
              onDeletePressed: () async {
                Navigator.of(context).pop(_WalletOptions.deleteWallet);
              },
              onWalletKeysPressed: showKeys
                  ? () => Navigator.of(context).pop(_WalletOptions.walletKeys)
                  : null,
              onAddAccountPressed: wallet is PivxWallet && !wallet.isViewOnly
                  ? () => Navigator.of(context).pop(_WalletOptions.addAccount)
                  : null,
              walletId: walletId,
            );
          },
        );

        if (context.mounted && func != null) {
          switch (func) {
            case _WalletOptions.signMessage:
              unawaited(showSignMessageDialog(context, walletId));
              break;
            case _WalletOptions.walletKeys:
              unawaited(showWalletKeys(context, walletId));
              break;
            case _WalletOptions.addAccount:
              unawaited(showPivxAddAccountDialog(context, ref, walletId));
              break;
            case _WalletOptions.deleteWallet:
              final result = await showDialog<bool?>(
                context: context,
                barrierDismissible: false,
                builder: (context) => Navigator(
                  initialRoute: DesktopDeleteWalletDialog.routeName,
                  onGenerateRoute: RouteGenerator.generateRoute,
                  onGenerateInitialRoutes: (_, __) {
                    return [
                      RouteGenerator.generateRoute(
                        RouteSettings(
                          name: DesktopDeleteWalletDialog.routeName,
                          arguments: walletId,
                        ),
                      ),
                    ];
                  },
                ),
              );

              if (result == true) {
                if (context.mounted) {
                  Navigator.of(context).pop();
                }
              }
              break;
          }
        }
      },
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 19, horizontal: 32),
        child: Row(
          children: [
            SvgPicture.asset(
              Assets.svg.ellipsis,
              width: 20,
              height: 20,
              color: Theme.of(context)
                  .extension<StackColors>()!
                  .buttonTextSecondary,
            ),
          ],
        ),
      ),
    );
  }
}

class WalletOptionsPopupMenu extends ConsumerWidget {
  const WalletOptionsPopupMenu({
    super.key,
    required this.onSignMessagePressed,
    required this.onDeletePressed,
    required this.onWalletKeysPressed,
    this.onAddAccountPressed,
    required this.walletId,
  });

  final VoidCallback onSignMessagePressed;
  final VoidCallback onDeletePressed;

  /// Null: no Wallet seed (or keys) item.
  final VoidCallback? onWalletKeysPressed;

  /// Null: no Add account item (only PIVX wallets with a phrase have one).
  final VoidCallback? onAddAccountPressed;
  final String walletId;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return Stack(
      children: [
        Positioned(
          top: 24,
          left: MediaQuery.of(context).size.width - 234,
          child: Container(
            width: 220,
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(
                Constants.size.circularBorderRadius * 2,
              ),
              color: Theme.of(context).extension<StackColors>()!.popupBG,
              boxShadow: [
                Theme.of(context).extension<StackColors>()!.standardBoxShadow,
              ],
            ),
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  _MenuItem(
                    icon: Assets.svg.pencil,
                    label: _WalletOptions.signMessage.prettyName,
                    onPressed: onSignMessagePressed,
                  ),
                  if (onWalletKeysPressed != null) ...[
                    const SizedBox(height: 8),
                    _MenuItem(
                      icon: Assets.svg.key,
                      label: walletSecretTitle(
                        ref.read(pWallets).getWallet(walletId),
                      ),
                      onPressed: onWalletKeysPressed!,
                    ),
                  ],
                  if (onAddAccountPressed != null) ...[
                    const SizedBox(height: 8),
                    _MenuItem(
                      icon: Assets.svg.plus,
                      label: _WalletOptions.addAccount.prettyName,
                      onPressed: onAddAccountPressed!,
                    ),
                  ],
                  const SizedBox(height: 8),
                  _MenuItem(
                    icon: Assets.svg.trash,
                    label: _WalletOptions.deleteWallet.prettyName,
                    onPressed: onDeletePressed,
                  ),
                ],
              ),
            ),
          ),
        ),
      ],
    );
  }
}

